    internal static string Read(int topic)
    {
        if (topic < 1 || topic > Additional.Length) return "";
        var comparer = StringComparer.Create(CultureInfo.GetCultureInfo("uz-Latn-UZ"), true);
        var terms = TopicAssessments.Read(topic).Select(entry => (entry.Term, Definition: entry.Definition.TrimEnd('.') + "."))
            .Concat(Additional[topic - 1].Select(value => value.Split('|', 2)).Select(pair => (Term: pair[0], Definition: pair[1])));
        return string.Join("\n", terms.OrderBy(entry => entry.Term, comparer)
            .Select(entry => $"{entry.Term} — {entry.Definition}"));
    }
